) AS (
  VALUES 
    (337::BIGINT, 'da el curso especialmente enfocado en matemática, si le gusta bastante esa parte siéntase libre, pero la mate solo ayuda en los quices, en realidad se programa un montón en el curso con Python. Pesado para ser una electiva, pero se pasa fácil y se aprende bastante si le interesa el tema.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra', 'Deja trabajos largos']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, '203f368a8ff55b2aa844b783ec51f9b3a82a5f5031eb606e0abe77f6770faa4a'::TEXT, ARRAY[50]::BIGINT[]),
    (337::BIGINT, 'La clase es muy teórica, explica todo muy bien. Deja trabajos largos pero no son tan difíciles después de un buen análisis. Sí hay que estar bien preparado para los quices, ya que son algo rudos. SIEMPRE alarga las clases, por lo que traten de no poner cursos después de esta clase.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2023-06-24T00:00:00+00:00'::TIMESTAMPTZ, '30ebac13ef7b843d77b3a5f60fd64c3816c3ab163cd91a397bb2e978178a7698'::TEXT, ARRAY[1162]::BIGINT[]),
    (337::BIGINT, 'Muy teórico. Explica de manera tan matemática que para la mayoría en lugar de aclarar los confunde más. En los trabajos prácticos casi ni ve el código, se centra en la documentación. No es claro en como la quiere. Casi no hay ejercicios de práctica para los quices. Las clases pueden ser aburridas.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Da crédito extra']::TEXT[], '2023-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'c9a75021164990e3073aeea2c14fb3d1b60bccb78d7e9a8670d0a1c24e6d1222'::TEXT, ARRAY[1162]::BIGINT[]),
    (337::BIGINT, 'Excelente curso con material preparado a la medida y trabajos muy practicos donde se entiende lo visto en clase.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Requiere mucha lectura']::TEXT[], '2023-01-25T00:00:00+00:00'::TIMESTAMPTZ, '55fa11bd0f1fff4b6617e1788aaa3649b62ce73bb34b7dd1cba9e6b51585d26c'::TEXT, ARRAY[334]::BIGINT[]),
    (337::BIGINT, 'Se enfoca dem en la mate, casi no vio estadistica y se enfoco en algoritmos.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos']::TEXT[], '2022-10-25T00:00:00+00:00'::TIMESTAMPTZ, 'ad3a8cdb85609c560332518d78a6fad69aee4de6d84516f9e1b975107386ac94'::TEXT, ARRAY[4479, 4475, 1058, 1057, 4847, 4608, 4916, 1811]::BIGINT[]),
    (337::BIGINT, 'Material difícil de entender, hay que apoyarse en recursos externos. Las clases se hacen largas y cansadas. Los temas presentados son muy interesantes y lo mejor es grabar la clase para repasarla varias veces. Ayuda muy poco o nada cuando le preguntas por un trabajo. Trabajos pract. muy interesantes'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Da crédito extra', 'Pocos exámenes']::TEXT[], '2022-06-17T00:00:00+00:00'::TIMESTAMPTZ, '50bbe087a92ed59ba2ca04b7ebe792bb17bafb89607de6aed98b4a6b9ae5058d'::TEXT, ARRAY[334]::BIGINT[]),
    (337::BIGINT, 'Si tu base matemática es baja, debes esforzarte bastante, pues para este curso es importante. Aunque al principio parece un curso de matemáticas, luego te das cuenta que los modelos que se revisan son más fáciles de entender y programar con el conocimiento matemático aprendido al inicio del curso.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2022-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'd3d1bf4e911aebed7ab4d8638d7c06aa05d52e51ee411d8db397351c1fdd74b8'::TEXT, ARRAY[334]::BIGINT[]),
    (337::BIGINT, 'Es amigable. Lo recomiendo para personas que ya saben algo de python, si a alguien que no sepa le toca con él prepárese para estudiar por cuenta propia ya que él no lo da todo en clase. En los proyectos puede calificar cosas que no pidió en un inicio así que entregue más de lo que él pide.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2022-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'a9569801a4fe6efa39549915fb001a0e19e62d7dce70912cdc71e96b72fc431d'::TEXT, ARRAY[315, 1022]::BIGINT[]),
    (337::BIGINT, 'Su enfoque científico agrega bastante complejidad a los cursos que imparte. El material de clase debe madurar un poco más, sobre todo en claridad y simplicidad. Metodología de solo tareas hace que se deba emplear bastante tiempo e investigación, lo cual beneficia al estudiante en aprendizaje.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Da crédito extra', 'Deja trabajos largos']::TEXT[], '2019-08-21T00:00:00+00:00'::TIMESTAMPTZ, '16d0b558c1227f4aa8827258ca95c0b833ba54cacb46620c8486e6a6cc2426d3'::TEXT, ARRAY[334]::BIGINT[]),
    (337::BIGINT, 'Se aprende una cantidad infinita. El profe está muy actualizado y enseña lo que se usa actualmente. La materia/clases son muy matemáticas entonces es difícil seguir el hilo. Da los apuntes con los que expone. Quices muy difíciles. 5 o 6 proyectos largos pero MUUUY chivas, con puntos extra merecidos.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra', 'Deja trabajos largos']::TEXT[], '2019-07-15T00:00:00+00:00'::TIMESTAMPTZ, 'ea62f71b4c5064fdd916fe6aab10acf3d6fbc898ee6830ec296e22884d48ae7c'::TEXT, ARRAY[1162]::BIGINT[]),
    (337::BIGINT, 'Excelente profesor, es exigente pero se aprende mucho. Muchas tareas. Los apuntes a veces no son muy claros, pero siempre hay bastante material de referencia.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases excelentes']::TEXT[], '2019-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'bbe002664bed98e82d5a7fa47af62efb684d28c8bf74fbd1d7911b38f8981417'::TEXT, ARRAY[331]::BIGINT[]),
    (337::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Brinda apoyo']::TEXT[], '2019-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'ead44ad2833db9fd528f4723a7ac64600d0726d73f474f3327f5be8cd1114c66'::TEXT, ARRAY[331]::BIGINT[]),
    (337::BIGINT, 'El dominio del tema es excelente, le falta experiencia para llevar un buen ritmo de clase.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Exámenes retadores']::TEXT[], '2019-06-13T00:00:00+00:00'::TIMESTAMPTZ, '6852cd2e959c732be8756b0f68f4a4badf128691b3f6fd1f75369ffb835be2ec'::TEXT, ARRAY[331]::BIGINT[]),
    (337::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-13T00:00:00+00:00'::TIMESTAMPTZ, '1b95c3d3f794b6809038608c4964bdbf17d855d3e258bdc1421fa020e79866df'::TEXT, ARRAY[331]::BIGINT[]),
    (337::BIGINT, 'Es un profesor que le gusta lo que está enseñando y por tanto aunque no explique de la mejor manera a veces transmite la pasión por los temas de estudio.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra', 'Aspectos de calificación claros']::TEXT[], '2019-06-13T00:00:00+00:00'::TIMESTAMPTZ, '5820ad3fb95b8dca4537c980062bb004696b425004f87920520dba76101101d0'::TEXT, ARRAY[1162]::BIGINT[]),
    (337::BIGINT, 'Es un buen profesor, siempre y cuando seas buen estudiante. Con esto me refiero a que si llevás una clase como IA con él es necesario que leas antes de cada clase y de fijo te va bien. Si no lees te atrasas con la materia y puede que te de sensación de no entender nada (los proyectos ayudan a eso).'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Da crédito extra']::TEXT[], '2019-06-10T00:00:00+00:00'::TIMESTAMPTZ, '9848d1904405bebddd521fb1d658be55932970bff809f06b4351677982b0d008'::TEXT, ARRAY[1162]::BIGINT[]),
    (337::BIGINT, 'Un curso que requiere una base matemática muy fuerte. Al inicio es un curso bastante pesado, pero los últimos trabajos resultan ser los más prácticos e interesantes. En resumen, un curso al que hay que dedicarle bastante tiempo.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2019-06-10T00:00:00+00:00'::TIMESTAMPTZ, '60ac985921d5b8bb07bc65b4aad9829d1e0aac708c60b9a404e2198e51a5cdcd'::TEXT, ARRAY[1162]::BIGINT[]),
    (337::BIGINT, 'Las clases fueron aburridas y muy complicadas al inicio, pero haciendo los proyectos y las tareas se pasa fácil el curso con muy buena nota. Los quices son complicados pero todos los proyectos tenían puntos extra.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra', 'Deja trabajos largos']::TEXT[], '2019-06-10T00:00:00+00:00'::TIMESTAMPTZ, '7cf4422f0276b9a1aedc9fa68c69edc7ff1df577a716b6403e22b648e7c99458'::TEXT, ARRAY[1162]::BIGINT[]),
    (337::BIGINT, 'Las clases pueden ser confusas y la materia no queda muy clara, pero al hacer las evaluaciones se aprende mucho y se obtiene una base muy sólida de Inteligencia Artificial'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Deja trabajos largos']::TEXT[], '2019-06-10T00:00:00+00:00'::TIMESTAMPTZ, 'c6d180c82c689f57b429c3e2b8a878bbf01b3b8fb887bd911d2af7c8cb3a0441'::TEXT, ARRAY[1162]::BIGINT[]),
    (337::BIGINT, 'Esperaba más de éste curso, no creí tener que llevar todas las mates de la carrera de manera avanzada y mucho menos tener que hacer demostraciones en LaTex. Como persona es muy amable, pero como profesor le cuesta demasiado transmitir el conocimiento.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2019-06-03T00:00:00+00:00'::TIMESTAMPTZ, 'c7349b1227c03daa0e00c20e305ede23b810321293686c16d5f05d91c4fe4151'::TEXT, ARRAY[1162]::BIGINT[]),
    (337::BIGINT, 'El curso no es lo más fácil de llevar, sin embargo con un poco de esfuerzo se pasa con buena nota. Saul tiene un dominio del tema que se hace claro y hace las clases interesantes. Muy recomendado si quiere entrarle a Pattern Recognition o Machine Learning.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra', 'Clases excelentes']::TEXT[], '2019-01-21T00:00:00+00:00'::TIMESTAMPTZ, '4a3f43e8fb195d0bf716854f11143f34790b04d0c0d2142926ad687788fd054f'::TEXT, ARRAY[1336, 1117]::BIGINT[]),
    (337::BIGINT, 'El curso es fácil y no quita tiempo. Uno aprende mucho con los trabajos prácticos que se sacan rápido (80%), solo el primero es un poco difícil y también hay un proyecto de investigación (20%). El profesor ayuda bastante si le pregunta. En general, recomendado el curso si le gusta estos temas.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Muchas tareas', 'Clases excelentes']::TEXT[], '2018-12-25T00:00:00+00:00'::TIMESTAMPTZ, '01d58c5521050525616aa996a4a35bceeefdd645e701d5b7f599d56626664dbf'::TEXT, ARRAY[1336, 1117]::BIGINT[]),
    (337::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-08T00:00:00+00:00'::TIMESTAMPTZ, '48c33421166b270d53075b739e186999b4d5c8d3e1e0c81ce2fa466fd2cdc158'::TEXT, ARRAY[3918]::BIGINT[]),
    (337::BIGINT, 'Curso que demanda mucho tiempo, pero se pasa con las tareas. Como profesor pésimo, pero sube el material para poder hacer las tareas'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'b6f61980fb008cbda6d46d248868011a75b6ae403ddec917841bc9451b4d7dd2'::TEXT, ARRAY[1336, 1117]::BIGINT[]),
    (337::BIGINT, 'Curso que demanda su tiempo, trate de encontrar un buen grupo de trabajo. Las primeras tareas no valen nada, al final del semestre uno se juega el 50% del curso. La progra es fácil. Las clases son aburridas pero al menos deja las presentaciones en internet. Se aprende bastante de métricas y calidad.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos proyectos grupales']::TEXT[], '2018-12-03T00:00:00+00:00'::TIMESTAMPTZ, '1531d53eb48cebb4e7253070c0aa7f9ba6ff50f8aa20f11d77b1000fcc7934e6'::TEXT, ARRAY[1056]::BIGINT[]),
    (337::BIGINT, 'El cruso es facil, las tareas son las mismas de todos los semestres, el proyecto es facil solo es modificar codigo, el profe se enfoca en dar la materia , las clases son aburridas pero deja las presentaciones , no hay asistencia obligatoria ,si mete asegurece que este dando algun curso de ia'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'ffb27f29b9b4fb5ff25eb624ebda97d4b6d158be51e526c99b0d3ba6064b764b'::TEXT, ARRAY[1056]::BIGINT[]),
    (337::BIGINT, 'Pésimo profesor, en las progras es más difícil entender el problema planteado que la progra en sí, piensa que todos estamos en 4to año y por ende manejamos conceptos avanzados cuando apenas es un curso de introducción.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2018-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'ac9d1e66ea69a8f548e72f73cc1483303bf771d319f7c26874f321fc8f5563ac'::TEXT, ARRAY[4866, 315]::BIGINT[]),
    (337::BIGINT, 'Es un curso tuanis si a usted le gusta la parte científica de la carrera, el principio es algo aburrido pero después se pone interesante'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2018-11-04T00:00:00+00:00'::TIMESTAMPTZ, '3087c46ee0601e22d29acaeddb060197d9a602601cf3bdcde45d01b5c51c0c41'::TEXT, ARRAY[1336, 1117]::BIGINT[]),
    (337::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2018-08-02T00:00:00+00:00'::TIMESTAMPTZ, '902b68d6785205b9de17dbb0ba65ad8a7375f60a0f1a3b7d2251b84781623e18'::TEXT, ARRAY[1056]::BIGINT[]),
    (337::BIGINT, 'Como no le abrieron la electiva de patrones, se desquito y el proyecto era hacer un software de reconocimiento facial y para enseñarnos la materia de patrones siempre dejo muy de lado la materia real del curso. Entenderle cuesta porque es muy desordenado en las ideas y en la pizarra. Mucho brete.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2018-06-27T00:00:00+00:00'::TIMESTAMPTZ, '58261660da8bfc86eb39ed241a8d731a0b58fec9989349a46c903996946f972f'::TEXT, ARRAY[1056]::BIGINT[]),
    (337::BIGINT, 'Excelente profe, se nota que le apasiona el tema y quiere que a uno también. A veces se va por la tangente, pero siempre relacionado a algún aspecto de computación y brinda una perspectiva interesante del estado de la industria. Me hubiera gustado verlo dando un curso como el de compu y sociedad.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Pocos exámenes', 'Deja trabajos largos']::TEXT[], '2018-06-27T00:00:00+00:00'::TIMESTAMPTZ, '555a0330558baf5f22860be75c8ee599284a76f20a513407d03d3968f58db41a'::TEXT, ARRAY[1056]::BIGINT[]),
    (337::BIGINT, 'Si usted es de primer ingreso ni se atreva a matricular con él. No va a aprender nada, se va a desmotivar bastante ya que el profesor en vez de enamorarlo de la carrera va a hacer todo lo contrario. Le falta empatía con los estudiantes y además no se sabe dar a entender'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '3df9a4778d77f1c2b18dfd095de394e00fc000aafbec0903e682fb8999775036'::TEXT, ARRAY[315, 4866]::BIGINT[]),
    (337::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'ad1845f4d4bf08004255a94649e34a39ee6c6a7936c8d27203c004350a81a462'::TEXT, ARRAY[315, 4866]::BIGINT[]),
    (337::BIGINT, 'Un profesor nada recomendado para primer ingreso. Podría decir que si quieres aprender mete con cualquier otro profesor que dará mejores resultados que el. No ayuda a motivar a los estudiantes al contrario, solo hace perder mas el interés por la carrera.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil', 'Exámenes retadores']::TEXT[], '2018-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'a0b90f4ee87b21a5a2e5393ed614692c14decf51385ab1d5251050e7d46792d0'::TEXT, ARRAY[315, 1022]::BIGINT[]),
    (337::BIGINT, 'Como curso introductorio es un poco mas dificil de lo comun, los examenes son dificiles y a mano,sin embargo hay suficiente practica.Las progras son trabajosas, pero se pueden realizar. Tambien habla mucho de su tema de patrones, pero con este profe se aprende bastante,es muy accesible y buena gente'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2017-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'a25196506c30e71167c06906fd53639c0980ed085bc3dc1581dffb31035f4f06'::TEXT, ARRAY[315, 1022]::BIGINT[]),
    (337::BIGINT, 'Deja mucho trabajo. El trabajo siempre está relacionado a patrones, y no le alcanza el tiempo para dar la materia de patrones y aseguramiento en un solo curso. No aterriza los temas y las clases se vuelven largas, pero es un profe que se esfuerza bastante.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2017-11-11T00:00:00+00:00'::TIMESTAMPTZ, 'd2b6f1536795eaf2dbb8ffbc2e0e7827f9f0c240ec454976d6a558e6c30de4f0'::TEXT, ARRAY[1056]::BIGINT[]),
    (337::BIGINT, 'Excelente profesor , de lo mejor que hay en la escuela de computación , si quiere llevar java 1 , java 2 como la latina no es su profe ,si quiere pensar como ingeniero y ser TEC matricule con él...'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Brinda apoyo']::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, '4b39f0d8f4ce9827b77344a8a5689d70cad8f48aa5cc64560fb414c65ad60e2a'::TEXT, ARRAY[3918, 1056]::BIGINT[]),
    (337::BIGINT, 'Los contenidos del curso son muy interesantes y el profesor se esfuerza por hacerlos llamativos. Primera vez que da el curso, por lo que hubo algunas fallas con el material que él mismo realiza, pero con tiempo se ve que puede ser un curso ya estructurado. Recomendada para electiva en el área de CS.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, '38d2e4aa47e92678b1dfd312f0d39dd4893d8fcef120c733a9cd833ddf253f0b'::TEXT, ARRAY[1336, 1117]::BIGINT[]),
    (337::BIGINT, 'El curso se vuelve extremadamente pesado al inicio debido a la gran deficiencia en matemáticas que se tiene en la carrera (El profesor tira toda la materia de un golpe). Luego de la primera mitad del semestre el curso se vuelve llevadero y comienza a tornarse sumamente interesante'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-19T00:00:00+00:00'::TIMESTAMPTZ, '02602286992c6dc960ca8f83bd959bcb5ef81460b94bd71c93b306b1734a8060'::TEXT, ARRAY[1336, 1117]::BIGINT[]),
    (337::BIGINT, 'Profe: super pura vida. Pros: el sabe cuando la gente se esfuerza y reconoce al final. Si puso atención e hizo parte de las progras le va super bien. Contras: solo a veces como dicen en otros comentarios, se emocionaba y se le pasaba la hora de salida jaja.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra', 'Aspectos de calificación claros']::TEXT[], '2017-01-31T00:00:00+00:00'::TIMESTAMPTZ, '73d36a2287c7e718f9b716787338becea8ca006cef9fdf962b430d79ac208619'::TEXT, ARRAY[1045]::BIGINT[]),
    (337::BIGINT, 'Buen profe, ayuda bastante en clase y da un ambiente de confianza para hacer consultas o preguntas de alguna parte que no esté clara. Solo que a veces se le va la mano con la hora de la salida, se emociona con el tema.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2017-01-28T00:00:00+00:00'::TIMESTAMPTZ, '792a2101cad8000fa07208f96e884d4085e08b4d6f8ede16285302751aa9bc96'::TEXT, ARRAY[1045]::BIGINT[]),
    (337::BIGINT, 'Buen profesor. Al principio el curso parece rudo pero conforme avanza se convierte más fácil. Explica bien en algunos temas pero en otros se le dificulta más.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-04T00:00:00+00:00'::TIMESTAMPTZ, '93acb6667222b0913007dd8fc1ba5beacde0afc233df98356b8c6309df67e9d1'::TEXT, ARRAY[1045]::BIGINT[]),
    (337::BIGINT, 'El mae es empachoso y da pereza, pero al final no es tan rudo. Eso si, le encanta dejar todo relacionado a lo que a el le gusta y no nota cuando los estudiantes no están entendiendo.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas']::TEXT[], '2016-12-02T00:00:00+00:00'::TIMESTAMPTZ, '5893b08c3c150cf5c0cee009f183525aa7065bb73a78e77c322ffbf162d16dd6'::TEXT, ARRAY[1151]::BIGINT[]),
    (337::BIGINT, 'Excelente como persona, ayuda bastante siempre que uno le solicite ayuda, el curso es un poco pesado por los contenidos y si es bastante trabajo pero se aprende como con ningún otro'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-01T00:00:00+00:00'::TIMESTAMPTZ, '68a5a0a990423356e13fc124a894254e92d3a26b1feea1e97ba7f28eacc264ed'::TEXT, ARRAY[1056]::BIGINT[]),
    (337::BIGINT, 'Bastantes trabajos, para ser Calidad pero se disfruta bastante, me gusto que le diera un toque mas computación científica al curso con computer graphics, como persona un 100, el curso es aburrido por el contenido pero gracias a las herramientas que usamos fue muy tuanis como uso de Selenium ,latex'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2016-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'e03b46d91c2d44188e112b781e627a8c933cb70ec01ca21cb8eb677e96ebaafc'::TEXT, ARRAY[1056]::BIGINT[]),
    (337::BIGINT, 'Es la primera vez que da el curso, entonces está un poco desubicado. Deja tareas/proyectos como si el curso valiera 4 o más créditos. Los proyectos son complejos, de lo que él ha trabajado o le gusta. Las clases son aburridas, y él nunca aterriza los temas.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2016-09-06T00:00:00+00:00'::TIMESTAMPTZ, 'e39aa303b7a6b507bc628f309005fbc79892db9ed7d72fbbabc69e8f8cf916f5'::TEXT, ARRAY[1056]::BIGINT[]),
    (337::BIGINT, 'Es realmente un buen profesor, ayuda bastante y le cuesta un poco darse a explicar pero explica las veces que usted le pregunte. Hace las progras algo rudas pero bastante interesantes y útiles, lo exámenes cuestan un poco, pero es simplemente estudiar y dedicar tiempo al curso, recomendado'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, '7c19a851be9a4c55ed0839b7a315fae2e5ece385b47753cdb577f83b72e6e188'::TEXT, ARRAY[4866, 1020]::BIGINT[]),
    (337::BIGINT, 'Al mae le interesa prepararlo bien, es buen profesor, deja trabajos algo complicados pero no imposibles, es solo de ponerle. Es buena gente, explica bien, aclara dudas, no dude en elegirlo.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Deja trabajos largos', 'Clases excelentes']::TEXT[], '2016-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'e0d18357bc0f8f9a4116d776e623bf5f3cc0f85c9eabaa93ac24f81b70511f6f'::TEXT, ARRAY[1020]::BIGINT[]),
    (337::BIGINT, 'Hace proyectos muy difíciles para alguien que viene empezando h no sabe nada, lo recomiendo para alguien que tenga conocimientos previos de programación, hace proyectos interesantes, de lo contrario busque otro profe sino quiere perder el curso'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-19T00:00:00+00:00'::TIMESTAMPTZ, '5cd5c4d98231bbec028789e3a391c1b816257c545c42430783eb2e3063ce12c4'::TEXT, ARRAY[1022]::BIGINT[]),
    (337::BIGINT, 'Es nuevo y le pone entusiasmo, sus exámenes son algo complicados pero nada que no se pueda resolver si se hace la práctica que el manda antes del examen, cuesta entenderle al principio pero uno termina entendiendole con los ejemplos, habla mucho de la UCR y Argentina.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-05T00:00:00+00:00'::TIMESTAMPTZ, 'a0113ae34aa8cf0fa67cb3c09ce684abf63b888a66a5dd3c2374991f10441b0f'::TEXT, ARRAY[1020]::BIGINT[]),
    (337::BIGINT, 'Muy buena gente, se interesa por el estudiante, al principio es un poco difícil de entender, pero al final se le entiende'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-04-12T00:00:00+00:00'::TIMESTAMPTZ, '70b262d80e40ae9eeb27c7720f839bdce077c7368d0ac3c0da173217600d464d'::TEXT, ARRAY[1020]::BIGINT[]),
    (337::BIGINT, 'Si van a llevar IA con saul, preparense para leer y tener que estudiar todas las semanas, es un curso muy rudo, hace muchos quizes y el curso es full matemático. Lo sentí demasiado pesado. Si le gusta la mate dele, pero si es un curso donde hay que ponerle bastante, si usted estudia pasa.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Muchos exámenes']::TEXT[], '2026-07-03T00:00:00+00:00'::TIMESTAMPTZ, '30a65d6b16de8b37c28e9b1314b5baff32289d965e56205e263f5457f0235766'::TEXT, ARRAY[1162]::BIGINT[]),
    (337::BIGINT, 'Le gusta profundizar en las fórmulas y enseñar de dónde salen. Está dispuesto a aclarar dudas. En sí el curso es muy matemático. Da un leve repaso de mate como para nivelar el grupo. Para que le saque el mejor provecho al curso es importante que repase cálculo y álgebra lineal. Los quices son duros.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2025-07-08T00:00:00+00:00'::TIMESTAMPTZ, '8750fc1d01989e22025c778e0057e25da37665ec3fae807686719024ba2539a2'::TEXT, ARRAY[1162]::BIGINT[]),
    (337::BIGINT, 'Los otros comentarios también aplican para IA, no sabe enseñar, solo menciona formulas, es muy arrogante, y califica las proyectos demasiado estricto, además de que no se sabe que es lo que pide. Y durante todo el semestre nos mantuvo motivados diciéndonos que no vamos a conseguir trabajo.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2025-06-04T00:00:00+00:00'::TIMESTAMPTZ, 'bbbff2cae1e850ae8b12bbc3d352a9f47be4a49d71d48a229cbbe499c7ca5f81'::TEXT, ARRAY[1162]::BIGINT[]),
    (337::BIGINT, 'Sumamente dificil, el profesor se centra en dar un curso de matematica, y no de computacion, no es debido a la materia del curso, en IA es igual, a diferencia de otros profes, le preocupa mucho la parte numerica, y lo monta a uno a hacer calculo despues de 2 años de no ver nada. No tomen el riesgo'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Da crédito extra', 'Exámenes retadores']::TEXT[], '2023-05-19T00:00:00+00:00'::TIMESTAMPTZ, '557853438ea68a26f896635f81d9c5b6d5a6c2cc9a27f7d1e6bb7482acfa3d85'::TEXT, ARRAY[50]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
